export interface Issue {
  title: string
  area: AreaKey
  ms: number
  scope: string
  ref?: string
  checks: string[]
  accept: string
  binding?: boolean
  gfi?: boolean
}

const i = (title: string, area: AreaKey, ms: number, scope: string, checks: string[], accept: string, extra: Partial<Issue> = {}): Issue =>
  ({ title, area, ms, scope, checks, accept, ...extra })

